+					*(out++) = 'x';
+					__nolibc_fallthrough;
+				default: /* 'x' and 'p' above */
+					u64toh_r(v, out);
+					break;
+				}
+				outstr = outbuf;
+			}
+			else if (ch == 's') {
+				outstr = va_arg(args, char *);
+				if (!outstr)
+					outstr="(null)";
+			}
+			else if (ch == 'm') {
