+				/* queue it verbatim */
+				continue;
+			}
+			else {
+				/* modifiers or final 0 */
+				if (ch == 'l') {
+					/* long format prefix, maintain the escape */
+					lpref++;
+				} else if (ch == 'j') {
+					lpref = 2;
+				}
+				escape = 1;
+				goto do_escape;
+			}
+			len = strlen(outstr);
+			goto flush_str;
+		}
