+{
+    const struct btf_member *members = (const void *)(t + 1);
+    const struct btf_member *found = NULL;
+    u32 i;
+
+    for (i = 0; i < BTF_INFO_VLEN(t->info); i++) {
+        const char *actual = susfs_btf_name(members[i].name_off);
+
+        if (!actual || strcmp(actual, name))
+            continue;
