+        bits = susfs_btf_member_bits(t, m);
+        if (bits % 8 || bits / 8 > t->size ||
+            !susfs_btf_matches(m->type, type) ||
+            (found && actual != bits / 8))
+            return -EINVAL;
+        actual = bits / 8;
+        found = true;
+    }
+    if (!found)
+        return -ENOENT;
+    *offset = actual;
+    return 0;
+}
+
+int susfs_btf_enum_value(const char *name, const char *member, int *value)
+{
